    public void save(Order order) {
        if (order.total() < 0) {
            throw new InvalidOrderException("negative total");
        }
        // ... persist the order
    }
}

// in the service:
try {
    orderDao.save(order);
} catch (DataAccessException e) {
    handleStorageProblem(e);
}

